SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "史书记四月初一日食。", "citation": "卷273·同光三年（925）·zztj-v273-y0925-p013·原文件第96行", "note": "原文：夏，四月，癸亥朔，日有食之。；核对说明：仅录史载天象，不附加天罚或现代计算的日食参数。", "status": "draft", "id": "d2058992-5e17-5a47-a788-2e701a537062", "subject_id": "63882391-12e9-54d4-96e4-73d00f43dd26", "source_id": "ed451357-4307-55dc-a6a1-8c8708d6255b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "925年四月癸亥朔", "citation": "卷273·同光三年（925）·zztj-v273-y0925-p013·原文件第96行", "note": "原文：夏，四月，癸亥朔，日有食之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "237e27f6-4e3f-5e8e-83f1-e8464c366d58", "subject_id": "63882391-12e9-54d4-96e4-73d00f43dd26", "source_id": "ed451357-4307-55dc-a6a1-8c8708d6255b"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧史同记四月癸亥朔日食。", "citation": "《旧五代史》卷三十二，段落 jiu-wudaishi-205deb4a7860-p001032；EPUB电子本，纸本及异文待核", "note": "原文：夏四月癸亥朔，日有蝕之。；核对说明：同月日印证；未经现代天文核算。", "status": "draft", "id": "b1b5a383-6661-51bf-a1e3-b3ff3d6903b0", "subject_id": "63882391-12e9-54d4-96e4-73d00f43dd26", "source_id": "f4112469-4b10-56f3-bf7d-0dfd6b809230"}, {"subject_table": "event", "field_path": "description", "claim_text": "追叙五台僧诚惠自称能降伏天龙、命风召雨。", "citation": "卷273·同光三年（925）·zztj-v273-y0925-p014·原文件第97行", "note": "原文：初，五台僧诚惠以妖妄惑人，自言能降伏天龙，命风召雨；；核对说明：原书妖妄是作者判断，能力只是诚惠自称，不录为真实能力。", "status": "draft", "id": "657f6fd5-40de-5e8c-8a98-cc89b589dd9b", "subject_id": "90a82dad-f875-57a6-a06a-8a1fe103a084", "source_id": "ed451357-4307-55dc-a6a1-8c8708d6255b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "925年四月叙及的前事，确年未载", "citation": "卷273·同光三年（925）·zztj-v273-y0925-p014·原文件第97行", "note": "原文：初，五台僧诚惠以妖妄惑人，自言能降伏天龙，命风召雨；；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "8ed9ac71-b7fb-532d-9909-d17bf53c30a3", "subje